ALTER TABLE public.ride_requests ADD COLUMN customer_quote_draft_id uuid REFERENCES public.trip_drafts(id), ADD COLUMN customer_quote_id uuid;
CREATE FUNCTION public.attach_confirmed_customer_invoice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_drafts;q jsonb;owner_user uuid;provider jsonb;bill jsonb;inv uuid;service text; BEGIN
 IF NEW.customer_quote_id IS NULL AND NEW.customer_quote_draft_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO d FROM public.trip_drafts WHERE id=NEW.customer_quote_draft_id AND user_id=NEW.actor_user_id AND workspace_id=NEW.workspace_id AND submitted_trip_id IS NULL FOR UPDATE;
 q:=d.customer_quote_history->-1;
 IF d.id IS NULL OR (q->>'id')::uuid IS DISTINCT FROM NEW.customer_quote_id OR EXISTS(SELECT 1 FROM public.trip_invoice_documents WHERE quote_id=NEW.customer_quote_id) THEN RAISE EXCEPTION 'Confirmed quote unavailable'; END IF;
 service:=CASE WHEN NEW.trip_kind='medical_delivery' THEN 'medical_delivery' WHEN NEW.transport_type='gurney' THEN 'stretcher' ELSE NEW.transport_type END;
 IF q->'trip'->>'service' IS DISTINCT FROM service OR q->'trip'->>'pickupDate' IS DISTINCT FROM NEW.pickup_date::text OR left(q->'trip'->>'pickupTime',5) IS DISTINCT FROM left(NEW.pickup_time::text,5) OR (q->'trip'->>'roundTrip')::boolean IS DISTINCT FROM NEW.round_trip OR q->>'formFingerprint' IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_object('pickupAddress',NEW.pickup_address,'pickupCity',NEW.pickup_city,'dropoffAddress',NEW.dropoff_address,'dropoffCity',NEW.dropoff_city,'patientWorkspaceId',NEW.patient_workspace_id,'additionalStops',NEW.additional_stops,'returnDate',NEW.return_date,'returnPickupTime',NEW.return_pickup_time)::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'Trip changed; confirm a new quote'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=NEW.workspace_id AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.account_type='provider' AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Invoice management unavailable';END IF;
 SELECT user_id INTO owner_user FROM public.workspace_members WHERE workspace_id=NEW.workspace_id AND role='owner' AND NOT is_contractor AND removed_at IS NULL ORDER BY created_at LIMIT 1;
 SELECT jsonb_build_object('name',w.display_name,'phone',CASE WHEN p.trip_dispatch_phone_designated THEN p.trip_dispatch_phone END) INTO provider FROM public.workspaces w LEFT JOIN public.provider_network_profiles p ON p.workspace_id=w.id WHERE w.id=NEW.workspace_id;
 IF NEW.patient_workspace_id IS NOT NULL THEN SELECT jsonb_build_object('name',w.display_name,'email',u.email,'userId',u.id) INTO bill FROM public.workspaces w JOIN public.workspace_members m ON m.workspace_id=w.id JOIN auth.users u ON u.id=m.user_id WHERE w.id=NEW.patient_workspace_id AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND u.email_confirmed_at IS NOT NULL ORDER BY m.created_at LIMIT 1;
 ELSE bill:=jsonb_build_object('name',trim(coalesce(NEW.trip_billing_first_name,NEW.patient_first_name)||' '||coalesce(NEW.trip_billing_last_name,NEW.patient_last_name)),'email',coalesce(NEW.trip_billing_email,NEW.patient_email)); END IF;
 INSERT INTO public.trip_invoice_documents(request_id,provider_workspace_id,patient_workspace_id,quote_id,quote_snapshot,provider_snapshot,bill_to_snapshot,total_cents,created_by,person_mfn_id,workspace_mfn_id) VALUES(NEW.id,NEW.workspace_id,NEW.patient_workspace_id,NEW.customer_quote_id,q,provider,bill,(q->>'totalCents')::integer,NEW.actor_user_id,NEW.creator_person_mfn_id,NEW.originating_workspace_mfn_id) RETURNING id INTO inv;
 INSERT INTO public.trip_invoice_events(invoice_id,action,actor_id,person_mfn_id,details) VALUES(inv,'invoice_ready',NEW.actor_user_id,NEW.creator_person_mfn_id,jsonb_build_object('quote_id',NEW.customer_quote_id));
 RETURN NEW; END $$;
CREATE TRIGGER zzzz_attach_confirmed_invoice AFTER INSERT ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.attach_confirmed_customer_invoice();
CREATE FUNCTION public.customer_quote_fingerprint(_form jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT encode(sha256(convert_to(jsonb_build_object('pickupAddress',_form->>'pickupAddress','pickupCity',_form->>'pickupCity','dropoffAddress',_form->>'dropoffAddress','dropoffCity',_form->>'dropoffCity','patientWorkspaceId',nullif(_form->>'patientWorkspaceId','')::uuid,'additionalStops',coalesce(_form->'additionalStops','[]'::jsonb),'returnDate',nullif(_form->>'returnDate','')::date,'returnPickupTime',nullif(_form->>'returnPickupTime','')::time)::text,'UTF8')),'hex') $$;
REVOKE ALL ON FUNCTION public.customer_quote_fingerprint(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.customer_quote_fingerprint(jsonb) TO authenticated,service_role;
CREATE FUNCTION public.get_trip_invoice_snapshot(_invoice uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.trip_invoice_documents;paid bigint;history jsonb;manage boolean; BEGIN IF NOT public.trip_invoice_access(_invoice,false) THEN RETURN NULL; END IF; SELECT * INTO i FROM public.trip_invoice_documents WHERE id=_invoice;
 SELECT coalesce(sum(amount_cents) FILTER(WHERE status='succeeded'),0),coalesce(jsonb_agg(jsonb_build_object('reference',id,'status',status,'amountCents',amount_cents,'refundedCents',amount_refunded_cents,'createdAt',created_at) ORDER BY created_at),'[]'::jsonb) INTO paid,history FROM public.trip_payments WHERE invoice_document_id=i.id;
 manage:=public.trip_invoice_access(i.id,true);
 RETURN jsonb_build_object('id',i.id,'mfnId',i.mfn_id,'requestId',i.request_id,'requestNumber',(SELECT mfn_id FROM public.ride_requests WHERE id=i.request_id),'providerName',i.provider_snapshot->>'name','providerPhone',i.provider_snapshot->>'phone','billTo',i.bill_to_snapshot->>'name','lines',i.quote_snapshot->'lines','quoteVersion',(i.quote_snapshot->>'version')::integer,'terms',i.quote_snapshot->>'terms','totalCents',i.total_cents,'paidCents',paid,'balanceCents',greatest(0,i.total_cents-paid),'status',i.status,'createdAt',i.created_at,'dueAt',i.due_at,'canManage',manage,'canPay',NOT manage,'paymentConfigured',false,'history',history); END $$;
REVOKE ALL ON FUNCTION public.get_trip_invoice_snapshot(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_trip_invoice_snapshot(uuid) TO authenticated,service_role;
CREATE FUNCTION public.list_request_invoices(_request uuid) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.get_trip_invoice_snapshot(i.id) FROM public.trip_invoice_documents i WHERE i.request_id=_request AND public.trip_invoice_access(i.id,false) ORDER BY i.created_at DESC $$;
REVOKE ALL ON FUNCTION public.list_request_invoices(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.list_request_invoices(uuid) TO authenticated,service_role;
CREATE FUNCTION public.patient_trip_contacts(_request uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips;ws uuid;d public.drivers;p public.provider_network_profiles;confirmed boolean; BEGIN IF NOT public.patient_request_access(_request) THEN RETURN NULL; END IF; SELECT * INTO t FROM public.trips WHERE ride_request_id=_request ORDER BY created_at DESC LIMIT 1; SELECT * INTO d FROM public.drivers WHERE id=t.driver_id;ws:=coalesce(d.workspace_id,t.network_provider_workspace_id); IF ws IS NULL THEN SELECT workspace_id INTO ws FROM public.ride_requests r JOIN public.workspaces w ON w.id=r.workspace_id WHERE r.id=_request AND w.account_type='provider'; END IF;SELECT * INTO p FROM public.provider_network_profiles WHERE workspace_id=ws;confirmed:=t.status IN ('confirmed','approved','assigned','in_progress','completed','scheduled','accepted'); RETURN jsonb_build_object('dispatchPhone',CASE WHEN confirmed AND p.trip_dispatch_phone_designated THEN p.trip_dispatch_phone END,'driverName',CASE WHEN t.driver_id IS NOT NULL AND t.status IN ('assigned','in_progress','completed') THEN trim(d.first_name||' '||d.last_name) END,'driverPhone',CASE WHEN t.driver_id IS NOT NULL AND t.status IN ('assigned','in_progress','completed') AND t.patient_contact_driver_id=t.driver_id AND t.patient_driver_provider_confirmed AND t.patient_driver_confirmed THEN t.patient_driver_phone END); END $$;
REVOKE ALL ON FUNCTION public.patient_trip_contacts(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.patient_trip_contacts(uuid) TO authenticated;
CREATE FUNCTION public.prepare_customer_invoice_payment(_invoice uuid,_env text,_account text,_payer uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.trip_invoice_documents;p public.trip_payments;owner_user uuid; BEGIN
 SELECT * INTO i FROM public.trip_invoice_documents WHERE id=_invoice FOR UPDATE; IF i.id IS NULL OR _env NOT IN ('sandbox','live') OR i.status NOT IN ('ready','sent','payment_pending','failed') OR i.total_cents<=0 OR NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='customer_invoice_collection' AND enabled) OR (_env='live' AND NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='customer_invoice_live_collection' AND enabled)) THEN RAISE EXCEPTION 'Payment unavailable'; END IF;
 SELECT user_id INTO owner_user FROM public.workspace_members WHERE workspace_id=i.provider_workspace_id AND role='owner' AND NOT is_contractor AND removed_at IS NULL ORDER BY created_at LIMIT 1;
 IF NOT EXISTS(SELECT 1 FROM public.provider_payout_accounts a WHERE a.user_id=owner_user AND a.workspace_id=i.provider_workspace_id AND a.environment=_env AND a.stripe_account_id=_account AND a.charges_enabled) THEN RAISE EXCEPTION 'Payment unavailable'; END IF;
 SELECT * INTO p FROM public.trip_payments WHERE invoice_document_id=i.id AND environment=_env AND status NOT IN ('failed','canceled') ORDER BY created_at DESC LIMIT 1;
 IF p.id IS NULL THEN INSERT INTO public.trip_payments(ride_request_id,payer_user_id,provider_user_id,environment,invoice_document_id,amount_cents,platform_fee_cents,status,invoice_idempotency_key,stripe_connected_account_id) VALUES(i.request_id,_payer,owner_user,_env,i.id,i.total_cents,0,'prepared','invoice_'||i.id::text||'_'||_env,_account) ON CONFLICT(invoice_idempotency_key) WHERE invoice_idempotency_key IS NOT NULL DO UPDATE SET invoice_idempotency_key=EXCLUDED.invoice_idempotency_key RETURNING * INTO p; END IF;
 IF p.status='succeeded' THEN RAISE EXCEPTION 'Payment unavailable'; END IF; UPDATE public.trip_invoice_documents SET status='payment_pending' WHERE id=i.id;
 RETURN jsonb_build_object('id',p.id,'idempotencyKey',p.invoice_idempotency_key,'sessionId',p.stripe_checkout_session_id,'amountCents',p.amount_cents,'account',p.stripe_connected_account_id); END $$;
REVOKE ALL ON FUNCTION public.prepare_customer_invoice_payment(uuid,text,text,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.prepare_customer_invoice_payment(uuid,text,text,uuid) TO service_role;